#include <memory>
#include <iostream>

void processData() {
  // Using unique_ptr for exclusive ownership
  auto ptr = std::make_unique<Data>(/*...*/);
  try {
    // ... process data using ptr ...
  } catch (const std::exception& e) {
    std::cerr << "Error: " << e.what() << std::endl;
    // Exception handled; unique_ptr destructor cleans up automatically.
  } 
  // No need for explicit delete; unique_ptr's destructor is called here
}

class Data {
public:
  Data(int val) : value(val) { std::cout << "Data created: " << value << std::endl; }
  ~Data() { std::cout << "Data destroyed: " << value << std::endl; }
  int value;
};
